import argparse,hashlib,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument("input");p.add_argument("bindings");p.add_argument("output");a=p.parse_args();d=json.loads(Path(a.input).read_text())
matches=[{"records":["PAY-2001","PAY-2001-DUP","B-002"],"classification":"DUPLICATE_CANDIDATE","basis":"same date, amount, counterparty, and reference; no merge by appearance alone"}]
normalized_records=[{"record_id":r["id"],"date":r.get("date",r.get("issue_date")),"posting_date":r.get("posting_date"),"payment_date":r.get("date") if r.get("id","").startswith("PAY-") else None,"amount":r.get("amount",r.get("principal",r.get("current_portion"))),"currency":r.get("currency","USD"),"counterparty":r.get("counterparty"),"account":r.get("account",r.get("account_id")),"source_id":r.get("source_id"),"source_location":r.get("source_location"),"source_fragment":json.dumps(r,sort_keys=True,separators=(",",":"))} for k in ["bank_entries","invoices","payments","ledger_entries","ar","ap","debt","covenants"] for r in d[k]]
